 "command": "python3 -c \"\nimport sqlite3;c=sqlite3.connect('var/dev.sqlite3');print(c.execute('select name from sqlite_master').fetchall())\"; cat scripts/migrate_dev.py"
}

{
 "command": "python3 scripts/migrate_dev.py && LEDGERLINE_ENV=dev python3 scripts/seed_dev.py"
}

